public class VOLTAGE_TO_INTENSITY_SRGB {
/**
     * Returns the intensity of an RGB component using the
     * sRGB gamma function.
     * 
     * @param val Value to convert.
     * @return Light intensity of the component.
     */
    double voltage_to_intensity_srgb(double val) {
        /* Handle invalid values before doing a gamma transform. */
        if (val < 0.0) {
			return 0.0;
		}
        if (val > 1.0) {
			return 1.0;
		}

        if (val <= 0.04045) {
            return val / 12.92;
        }
        return Math.pow((val + 0.055) / 1.055, 2.4);
    }
}

public class ISBINARY {
/**
     * Indicates whether the given SQL data type is a binary type.
     *
     * @param type one of the constants from <code>java.sql.Types</code>
     * @return <code>true</code> if the given type is <code>BINARY</code>,'
     *         <code>VARBINARY</code>, or <code>LONGVARBINARY</code>;
     *         <code>false</code> otherwise
     */
    public boolean isBinary(int type) {
        switch (type) {
            case java.sql.Types.BINARY:
            case java.sql.Types.VARBINARY:
            case java.sql.Types.LONGVARBINARY:
                return true;
            default:
                return false;
        }
    }
}

public class UNSIGNEDLEB128SIZE {
/**
     * Gets the number of bytes in the unsigned LEB128 encoding of the
     * given value.
     *
     * @param value the value in question
     * @return its write size, in bytes
     */
    public static int unsignedLeb128Size(int value) {
        // TODO: This could be much cleverer.

        int remaining = value >>> 7;
        int count = 0;

        while (remaining != 0) {
            value = remaining;
            remaining >>>= 7;
            count++;
        }

        return count + 1;
    }
}

public class GETROLLEDVALUE {
/**
     * Returns the new value after 'roll'ing the specified value and amount.
     */
    public static int getRolledValue(int value, int amount, int min, int max) {
        assert value >= min && value <= max;
        int range = max - min + 1;
        amount %= range;
        int n = value + amount;
        if (n > max) {
            n -= range;
        } else if (n < min) {
            n += range;
        }
        assert n >= min && n <= max;
        return n;
    }
}

public class COMPARESTRING {
/**
	 * Compares the two times.
	 * 
	 * @param checktimes
	 *            the times that the string display.
	 * @param countstring
	 *            the golden times.
	 * @return true if two times are same.
	 * @throws Exception
	 *             if any exception
	 */
	public boolean compareString( int checktimes, int countstring )
	{
		boolean same = true;
		StringBuffer errorText = new StringBuffer( );
		try
		{
			if ( checktimes == countstring )
				same = true;
			else
				same = false;
		}
		catch ( Exception e )
		{
			errorText.append( e.toString( ) );
		}
		return same;

	}
}

public class REQUIREESCAPING {
/**
     * Can be overrided. Return true if the character
     * needs to be escaped.
     */
    public boolean requireEscaping(int ch) {
        if(ch>=128)     return true;

        // control characters
        if( ch<0x20 && " \t\r\n".indexOf(ch)==-1 )  return true;

        return false;
    }
}

